133 apps/ai/vllm.tf
data "google_compute_image" "vllm_base" {
  project = local.project_id[terraform.workspace]
  family  = "vllm-prod"
}

resource "google_compute_address" "vllm_ilb" {
  name         = "vllm-ilb-${terraform.workspace}"
  subnetwork   = local.subnet_ids["apps-${terraform.workspace}"]
  address_type = "INTERNAL"
  purpose      = "GCE_ENDPOINT"
  region       = local.region.principal
}

resource "google_compute_instance_template" "vllm" {
  name_prefix  = "vllm-${terraform.workspace}-"
  machine_type = "n1-standard-4"
  region       = local.region.principal

  scheduling {
    provisioning_model  = "SPOT"
    preemptible         = true
    on_host_maintenance = "TERMINATE"
    automatic_restart   = false
  }

  guest_accelerator {
    type  = "nvidia-tesla-t4"
    count = 1
  }

  disk {
    source_image = data.google_compute_image.vllm_base.self_link
    disk_size_gb = 100
    disk_type    = "pd-ssd"
    boot         = true
    auto_delete  = true
    disk_encryption_key {
      kms_key_self_link = "${[for item in local.kms_key : item if can(regex(".*/compute-engine$", item))][0]}/cryptoKeys/compute-engine"
    }
  }

  network_interface {
    network    = local.network
    subnetwork = local.subnet_ids["apps-${terraform.workspace}"]
  }

  service_account {
    email  = local.sa["compute-engine"]
    scopes = ["cloud-platform"]
  }

  metadata = {
    startup-script = file("${path.module}/files/vllm-startup.sh")
  }

  tags   = ["ssh", "vllm"]
  labels = merge(local.default_labels, { service = "vllm" })

  lifecycle {
    create_before_destroy = true
  }
}

resource "google_compute_region_health_check" "vllm" {
  name                = "vllm-health-${terraform.workspace}"
  region              = local.region.principal
  check_interval_sec  = 30
  timeout_sec         = 10
  healthy_threshold   = 2
  unhealthy_threshold = 3

  http_health_check {
    port         = 8000
    request_path = "/health"
  }
}

resource "google_compute_region_instance_group_manager" "vllm" {
  name               = "vllm-mig-${terraform.workspace}"
  base_instance_name = "vllm"
  region             = local.region.principal
  target_size        = 1

  distribution_policy_zones        = ["us-east1-b", "us-east1-c", "us-east1-d"]
  distribution_policy_target_shape = "ANY_SINGLE_ZONE"

  version {
    instance_template = google_compute_instance_template.vllm.self_link
  }

  named_port {
    name = "vllm-api"
    port = 8000
  }

  auto_healing_policies {
    health_check      = google_compute_region_health_check.vllm.self_link
    initial_delay_sec = 1800
  }

  update_policy {
    type                         = "OPPORTUNISTIC"
    minimal_action               = "REPLACE"
    instance_redistribution_type = "NONE"
    max_surge_fixed              = 3
    max_unavailable_fixed        = 0
  }
}

resource "google_compute_region_backend_service" "vllm" {
  name                  = "vllm-backend-${terraform.workspace}"
  region                = local.region.principal
  protocol              = "TCP"
  load_balancing_scheme = "INTERNAL"
  health_checks         = [google_compute_region_health_check.vllm.self_link]

  backend {
    group          = google_compute_region_instance_group_manager.vllm.instance_group
    balancing_mode = "CONNECTION"
  }
}

resource "google_compute_forwarding_rule" "vllm" {
  name                  = "vllm-ilb-${terraform.workspace}"
  region                = local.region.principal
  load_balancing_scheme = "INTERNAL"
  backend_service       = google_compute_region_backend_service.vllm.self_link
  ip_address            = google_compute_address.vllm_ilb.self_link
  ip_protocol           = "TCP"
  ports                 = ["8000"]
  subnetwork            = local.subnet_ids["apps-${terraform.workspace}"]
  network               = local.network
}

